'use strict';

const browser = require('@wxt-dev/browser');

function createI18n() {
  const t = (key, ...args) => {
    let sub;
    let count;
    args.forEach((arg, i) => {
      if (arg == null) ; else if (typeof arg === "number") {
        count = arg;
      } else if (Array.isArray(arg)) {
        sub = arg;
      } else {
        throw Error(
          `Unknown argument at index ${i}. Must be a number for pluralization, substitution array, or options object.`
        );
      }
    });
    if (count != null && sub == null) {
      sub = [String(count)];
    }
    let message;
    if (sub?.length) {
      const stringSubs = sub?.map((sub2) => String(sub2));
      message = browser.browser.i18n.getMessage(key.replaceAll(".", "_"), stringSubs);
    } else {
      message = browser.browser.i18n.getMessage(key.replaceAll(".", "_"));
    }
    if (!message) {
      console.warn(`[i18n] Message not found: "${key}"`);
    }
    if (count == null) return message;
    const plural = message.split(" | ");
    switch (plural.length) {
      // "n items"
      case 1:
        return plural[0];
      // "1 item | n items"
      case 2:
        return plural[count === 1 ? 0 : 1];
      // "0 items | 1 item | n items"
      case 3:
        return plural[count === 0 || count === 1 ? count : 2];
      default:
        throw Error("Unknown plural formatting");
    }
  };
  return { t };
}

exports.createI18n = createI18n;
